import{_ as a,o as s,c as t,a3 as i}from"./chunks/framework.CpLciM8b.js";const g=JSON.parse('{"title":"AI root-cause analysis","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/ai-rca.md","filePath":"concepts/ai-rca.md","lastUpdated":1785840738000}'),n={name:"concepts/ai-rca.md"};function r(o,e,l,h,d,p){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="ai-root-cause-analysis" tabindex="-1">AI root-cause analysis <a class="header-anchor" href="#ai-root-cause-analysis" aria-label="Permalink to &quot;AI root-cause analysis&quot;">​</a></h1><p>Root-cause is normally manual archaeology — digging through logs, stack traces, screenshots, and git blame for 20–40 minutes an incident. Flakemetry turns that into a structured <strong>likely cause + suggested action</strong>, without sending every failure to an LLM.</p><h2 id="cluster-first-ask-second" tabindex="-1">Cluster first, ask second <a class="header-anchor" href="#cluster-first-ask-second" aria-label="Permalink to &quot;Cluster first, ask second&quot;">​</a></h2><p>Sending every failure to a model would be slow and expensive. Instead, failures are <strong>normalized</strong> (secrets and PII scrubbed, volatile detail stripped) and <strong>clustered by error signature</strong>. Only a genuinely <em>new</em> signature reaches the model; repeat failures reuse the cached analysis for their cluster. Root-cause without a per-failure bill.</p><h2 id="budget-gated-and-provider-agnostic" tabindex="-1">Budget-gated and provider-agnostic <a class="header-anchor" href="#budget-gated-and-provider-agnostic" aria-label="Permalink to &quot;Budget-gated and provider-agnostic&quot;">​</a></h2><p>AI RCA is off until a provider is configured. When on, the worker sends only new deduplicated signatures and <strong>stops for the day once the token budget is spent</strong>, so the cost is bounded and predictable. The provider is pluggable — hosted <strong>Claude</strong> or a local <strong>Ollama</strong> model — so you can keep failure data entirely on your own infrastructure.</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><p>For each new signature the RCA panel offers a concise, structured explanation: the likely cause and a suggested next action, grounded in the normalized failure and its history. It is a starting point that collapses the first 20 minutes of triage, not a replacement for judgement.</p><p>The architecture is documented in the <a href="https://github.com/AKogut/flakemetry/wiki/AI-RCA-Architecture" target="_blank" rel="noreferrer">AI RCA wiki page</a>. Provider and budget configuration live in the <a href="/flakemetry/v/2026-09-30/reference/configuration">Configuration reference</a>.</p><h2 id="keeping-it-honest" tabindex="-1">Keeping it honest <a class="header-anchor" href="#keeping-it-honest" aria-label="Permalink to &quot;Keeping it honest&quot;">​</a></h2><p>An analysis can be marked helpful or not from the RCA panel, and a reviewer can write what the real cause actually was. Only those written corrections become evaluation cases — a bare thumbs-down says an answer was wrong without saying what right looks like, and there is nothing to score against that.</p><p>Prompts are versioned, and every report records which version produced it, so a change in the numbers can be attributed to a prompt rather than guessed at:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># score the active prompt and keep the result as a baseline</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @flakemetry/worker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eval</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">projectI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --write-baseline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> base.json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># a candidate prompt has to beat it, or the command exits non-zero</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @flakemetry/worker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eval</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">projectI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prompt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --baseline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> base.json</span></span></code></pre></div><p>Scoring is keyword recall against the correction, not a model grading a model. It is blunt and says nothing about whether an explanation reads well, but it is deterministic and needs no provider to compute — a judge model would make the measure itself a moving target. An answer that cannot be parsed counts as unanswered rather than merely wrong, tracked separately, because a prompt that stops emitting JSON is a different failure from one that explains badly.</p>`,14)])])}const k=a(n,[["render",r]]);export{g as __pageData,k as default};
